  return `<article class="casino casino-${i+1} ${active?'available':''} ${staged?'selected':''} ${t.effect!=='classic'?'special':''}"><button class="table-target" data-face="${i+1}" ${active?'':'disabled'} aria-label="${i+1}号${t.name}，总奖金${money(sum(t.notes))}，${active?`放入${n}颗`:'当前不可放置'}"><div class="casino-head"><span class="face">${die(i+1)}</span><div><h3>${t.name}</h3><div class="casino-total">总额 <strong>${money(sum(t.notes))}</strong></div></div></div><div class="banknotes" aria-label="${t.notes.map(money).join('、')}">${t.notes.map((value,noteIndex)=>{const k=claims.findIndex(a=>a.amount===value),a=k<0?null:claims.splice(k,1)[0];return `<span data-note="${noteIndex}" data-owner="${a?a.player:'none'}" style="--owner:${a?COLORS[a.player]:'#dec98d'}">${money(value)}<small>${a?(a.player===game.hero?'你':game.players[a.player].name)+(done?' 获得':' 暂领'):'待分配'}</small></span>`;}).join('')}</div><div class="counts">${v.counts.map((c,j)=>`<span data-player="${j}" style="--pc:${COLORS[j]}" class="pile ${c?'':'empty'} ${o.ties.includes(j)?'tied':''}" title="${esc(game.players[j].name)}：${c}颗骰子（${bigCount(v,j)}大），加成${v.bonus[j]}，合计${tableWeight(v,j)}"><small>${SYMBOL[j]}</small>${c?tableWeight(v,j):'–'}${bigCount(v,j)?`<small class="pile-big">${bigCount(v,j)}大</small>`:''}</span>`).join('')}</div><div class="forecast">${forecast}${staged&&MINIGAMES.includes(t.effect)&&!t.played[game.turn]?' · 小游戏加成待定':''}</div></button><button class="effect" data-info="${i+1}" aria-label="查看${i+1}号赌场规则：${fx.name}"><span>${t.effect!=='classic'?'✦':'◇'} ${fx.name}</span><span>ⓘ</span></button></article>`;
