function abilityBar(){return game.skills?`<section class="ability-bar" aria-label="角色技能"><span>✦ 角色技能版</span>${game.players.map((p,i)=>`<button data-skill="${i}" style="--pc:${COLORS[i]}" ${preview?'disabled':''}><b>${SYMBOL[i]} ${skillFor(game,i).name}</b><small>${roleOf(game,i)===0?'被动 · 每轮9骰':p.used?'本轮已用':isHuman(game,i)?'点击发动':'电脑 · 尚未发动'}</small></button>`).join('')}</section>`:'';}
