  app.classList.toggle('dock-active',!preview&&!['settled','finished'].includes(game.phase));app.classList.toggle('last-round',!preview&&game.round===4);finalMood.update(!preview&&game.round===4&&!['settled','finished'].includes(game.phase)&&!modal.open&&!cinema.active&&!tutorial.active&&!exam.active);
  document.documentElement.classList.toggle('no-motion',!prefs.motion);
